const validate = function validateSyncTasks({ tasks }) {
  return {
    tasks: tasks.map((task) => {
      if (typeof task.id !== "string" || !task.id || task.id.length > 2000)
        throw new Error("A Todoist task has an invalid text ID");
      if (typeof task.content !== "string" || !task.content || task.content.length > 2000)
        throw new Error("A Todoist task title cannot fit in a Notion title field");
      if (
        !Array.isArray(task.labels) ||
        task.labels.some((label) => typeof label !== "string" || !label)
      )
        throw new Error("Todoist did not return the task label names");
      if (task.description != null && typeof task.description !== "string")
        throw new Error("A Todoist task has an invalid description");
      return {
        id: task.id,
        content: task.content,
        description: task.description ?? "",
        labels: task.labels,
      };
    }),
  };
};

return validate({ tasks: $input.all().map((item) => item.json) }).tasks.map((json, index) => ({
  json,
  pairedItem: { item: index },
}));

const prepare = function prepareSyncUpdates({ created, tasks, sourceLabel, sentLabel }) {
  if (typeof sentLabel !== "string" || !sentLabel)
    throw new Error("Configure a completed-sync label");
  if (
    created.length !== tasks.length ||
    created.some(({ taskId }, index) => taskId !== tasks[index].id)
  )
    throw new Error("Notion page results are not associated with their Todoist tasks");
  const updates = created.map(({ page }, index) => {
    const task = tasks[index];
    return {
      taskId: task.id,
      labels: [...new Set([...task.labels.filter((label) => label !== sourceLabel), sentLabel])],
      description: "Notion Link:  " + page.url + "\n\n" + task.description,
    };
  });
  return { updates };
};

const tasks = $input.all().map((_, index) => $("Prepare task batch").itemMatching(index).json);
const created = $input.all().map((item, index) => ({ taskId: tasks[index].id, page: item.json }));
return prepare({
  created,
  tasks,
  sourceLabel: $node["Get all tasks with specific label"].parameter.filters.labelId,
  sentLabel: "sent",
}).updates.map((json, index) => ({ json, pairedItem: { item: index } }));
